SELECT COUNT(*) AS rentals_2025
FROM rental
WHERE EXTRACT(YEAR FROM rental_date AT TIME ZONE 'UTC') = 2025;

SELECT ROUND(AVG(EXTRACT(EPOCH FROM (rental_date - prev_rental))/86400.0), 2) AS avg_days_between_rentals
FROM (
  SELECT rental_date, LAG(rental_date) OVER (PARTITION BY customer_id ORDER BY rental_date) AS prev_rental
  FROM rental
) t
WHERE prev_rental IS NOT NULL;

SELECT COUNT(*) AS num_films_longer_than_avg
FROM film
